mapper.select:
select v.id, v.title, v.duration, v.cover_key, v.create_time, v.view_count, u.nickname
from video v left join user u on v.user_id=u.id


        (v.title like CONCAT('%',#{dto.keyword},'%') or u.nickname like CONCAT('%',#{dto.keyword},'%'))


        and v.status = #{dto.status}

    and v.user_id = #{userId}

order by v.${dto.orderBy}  ${dto.order}

    , (v.title LIKE CONCAT('%',#{dto.keyword},'%')) DESC

select v.id, v.title, v.duration, v.cover_key, v.create_time, v.view_count, u.nickname
from video v
left join user u
on v.user_id = u.id
where v.status = 2 

    and ( v.create_time < #{cursorTime}
        or(v.create_time = #{cursorTime} and v.id < #{cursorId} )
    )

order by v.create_time desc, v.id desc
limit #{size}

select v.id, v.title, v.create_time create_time, v.duration, v.cover_key, vl.create_time cursor_time, vl.id cursor_id, v.view_count, u.nickname
from video_like vl
join video v on vl.video_id = v.id
left join user u on v.user_id = u.id
where vl.user_id = #{userId} and v.status = 2

    and ( vl.create_time < #{cursorTime}
    or(vl.create_time = #{cursorTime} and vl.id < #{cursorId} )
    )

order by vl.create_time desc, vl.id desc
limit #{size}

select v.id, v.title, v.create_time create_time, v.duration, v.cover_key, vf.create_time cursor_time, vf.id cursor_id, v.view_count, u.nickname
from video_favorite vf
join video v on vf.video_id = v.id
left join user u on v.user_id = u.id
where vf.user_id = #{userId} and v.status = 2

    and ( vf.create_time < #{cursorTime}
    or(vf.create_time = #{cursorTime} and vf.id < #{cursorId} )
    )

order by vf.create_time desc, vf.id desc
limit #{size}
